'use client';
import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { supabaseBrowser } from '@/lib/supabase/browser';

/**
 * Landing page for emailed Supabase links (teacher invitation, password reset).
 *
 * Why this is more than getSession(): invitations are generated by the server (admin API) and Supabase answers them with the
 * IMPLICIT style redirect  …/auth/callback#access_token=…&refresh_token=…&type=invite .
 * The browser client in this app is a PKCE client, and a PKCE client deliberately REJECTS implicit tokens in the URL
 * ("Not a valid PKCE flow url"), so no session was ever created and the page timed out. We therefore read the tokens
 * ourselves and hand them to setSession(). PKCE (?code=) and token_hash (?token_hash=&type=) links are handled too.
 */
const OTP_TYPES = ['invite', 'recovery', 'signup', 'magiclink', 'email', 'email_change'] as const;
const EXPIRED = 'This link has expired or was already used. Ask the administrator to send a new invitation, or use "Forgot password" on the login page.';

export default function Callback() {
  const router = useRouter();
  const [err, setErr] = useState('');
  useEffect(() => {
    const sb = supabaseBrowser();
    const q = new URLSearchParams(location.search);
    const h = new URLSearchParams(location.hash.replace(/^#/, ''));
    const rawNext = q.get('next') || '/set-password';
    const next = rawNext.startsWith('/') && !rawNext.startsWith('//') ? rawNext : '/set-password'; // never redirect off-site
    const fail = (m: string) => setErr(m);
    (async () => {
      try {
        // 0) Supabase reported a problem (expired / already used / not allowed)
        if (h.get('error') || q.get('error')) return fail(EXPIRED);

        // 1) Implicit-style invitation / recovery link: #access_token=…&refresh_token=…
        const at = h.get('access_token'), rt = h.get('refresh_token');
        if (at && rt) {
          const { error } = await sb.auth.setSession({ access_token: at, refresh_token: rt });
          if (error) return fail(EXPIRED);
          return router.replace(next);
        }
        // 2) PKCE link: ?code=…
        const code = q.get('code');
        if (code) {
          const { error } = await sb.auth.exchangeCodeForSession(code);
          if (error) return fail(EXPIRED);
          return router.replace(next);
        }
        // 3) Custom e-mail template link: ?token_hash=…&type=invite|recovery
        const th = q.get('token_hash'), type = q.get('type') as (typeof OTP_TYPES)[number] | null;
        if (th && type && OTP_TYPES.includes(type)) {
          const { error } = await sb.auth.verifyOtp({ token_hash: th, type });
          if (error) return fail(EXPIRED);
          return router.replace(next);
        }
        // 4) Already signed in (e.g. page refreshed after the link was consumed)
        const { data } = await sb.auth.getSession();
        if (data.session) return router.replace(next);
        fail(EXPIRED);
      } catch { fail(EXPIRED); }
    })();
  }, [router]);
  return (
    <div className="flex min-h-screen items-center justify-center p-4 text-sm">
      {err ? <div className="max-w-sm text-center"><p className="mb-3 text-red-700">{err}</p><a className="text-maroon underline" href="/login">Go to login</a></div> : 'Signing you in…'}
    </div>
  );
}
